-- 한 트랜잭션으로 넣는다. `set local` 은 트랜잭션 안에서만 듣기 때문에,
-- 감싸지 않으면 재적재 때 지역 변경 트리거가 region_source 를 manual 로
-- 바꿔 버려 다음 적재가 그 행을 영영 갱신하지 못한다.
begin;
set local app.region_batch = 'on';

on conflict (tour_area_code) do update set
  name = excluded.name, lat = excluded.lat, lng = excluded.lng, sort_order = excluded.sort_order;

on conflict (tour_area_code, tour_sigungu_code) do update set
  name = excluded.name, ldong_cd = excluded.ldong_cd, lat = excluded.lat,
  lng = excluded.lng, sort_order = excluded.sort_order;

on conflict (id) do update set
  name = excluded.name, category = excluded.category,
  address = excluded.address, lat = excluded.lat, lng = excluded.lng,
  image_url = excluded.image_url, summary = excluded.summary,
  open_hours = excluded.open_hours, phone = excluded.phone,
  source_modified_at = excluded.source_modified_at,
  tour_area_code = case when public.places.region_source = 'manual'
    then public.places.tour_area_code else excluded.tour_area_code end,
  tour_sigungu_code = case when public.places.region_source = 'manual'
    then public.places.tour_sigungu_code else excluded.tour_sigungu_code end,
  region_source = case when public.places.region_source = 'manual'
    then 'manual'::region_source_kind else excluded.region_source end,
  region_note = case when public.places.region_source = 'manual'
    then public.places.region_note else excluded.region_note end;

